43	/**
44	 * Added at the very end of every premium, after all percentage modifiers, so
45	 * no surcharge or discount is ever computed on top of it.
46	 */
47	const PROCESSING_FEE = 5;
48	
49	/**
50	 * Rates are kept as exact numerator/denominator fractions rather than float
51	 * multipliers (10 / 100, never 1.1) so intermediate amounts stay exact and
52	 * only the final premium is rounded.
53	 */
54	const percent = (amount: number, rate: number): number => (amount * rate) / 100;
55	
56	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
57	const CURSE_SURCHARGE_PERCENT = 50;
58	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
59	const HIGH_ENCHANTMENT_THRESHOLD = 5;
60	const LOYALTY_DISCOUNT_PERCENT = 20;
61	const LOYALTY_THRESHOLD_YEARS = 2;
62	
63	/**
64	 * Everything the pricing rules need to know about an item type lives here, so
65	 * that "what is a rune?" has a single answer. Components are the small parts
66	 * (runes, moonstones) that can be bought as a building block; main items
67	 * (swords, amulets, ...) never form a block.
68	 */
69	const ITEM_TYPES: Record<string, { unitPremium: number; isComponent: boolean }> =
70	  {
71	    sword: { unitPremium: 100, isComponent: false },
72	    amulet: { unitPremium: 60, isComponent: false },
73	    staff: { unitPremium: 80, isComponent: false },
74	    potion: { unitPremium: 40, isComponent: false },
75	    rune: { unitPremium: 25, isComponent: true },
76	    moonstone: { unitPremium: 25, isComponent: true },
77	  };
78	
79	/** A building block of 3 alike components is offered at this base premium. */
80	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
81	const COMPONENT_BLOCK_SIZE = 3;
82	
83	/** Tallies how many items of each type a policy covers, e.g. [["rune", 3]]. */
84	const countByType = (items: Item[]): [string, number][] => {
85	  const counts = new Map<string, number>();
86	  for (const item of items) {
87	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
88	  }
89	  return [...counts];
90	};
91	
92	/**
93	 * Prices every item of one type together, because exactly 3 alike components
94	 * form a block charged as one. "Alike" means the same type, and the block does
95	 * not repeat: 4 or 7 runes are each priced per item.
96	 */
97	const basePremiumForType = (type: string, count: number): number => {
98	  const { unitPremium, isComponent } = ITEM_TYPES[type];
99	  return isComponent && count === COMPONENT_BLOCK_SIZE
100	    ? COMPONENT_BLOCK_BASE_PREMIUM
101	    : count * unitPremium;
102	};
103	
104	const sumOfBasePremiums = (items: Item[]): number =>
105	  countByType(items).reduce(
106	    (sum, [type, count]) => sum + basePremiumForType(type, count),
107	    0,
108	  );
109	
110	/**
111	 * Item-specific modifiers: each applies to one item and is charged as a
112	 * percentage of THAT item's unit premium, never of the policy total.
113	 * They stack — an item matching several rules is charged for each.
114	 *
115	 * Unit premium, not the item's share of the policy base: the two differ only
116	 * for components inside a block of 3 (billed 60 G for three 25 G runes), and
117	 * no test pins down a surcharged component yet. Revisit when one does.
118	 */
119	const ITEM_MODIFIERS: { appliesTo: (item: Item) => boolean; rate: number }[] = [
120	  { appliesTo: (item) => item.cursed === true, rate: CURSE_SURCHARGE_PERCENT },
121	  {
122	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
123	    rate: HIGH_ENCHANTMENT_SURCHARGE_PERCENT,
124	  },
125	];
126	
127	const surchargeForItem = (item: Item): number =>
128	  ITEM_MODIFIERS.filter(({ appliesTo }) => appliesTo(item)).reduce(
129	    (sum, { rate }) => sum + percent(ITEM_TYPES[item.type].unitPremium, rate),
130	    0,
131	  );
132	
133	const sumOfItemSurcharges = (items: Item[]): number =>
134	  items.reduce((sum, item) => sum + surchargeForItem(item), 0);
135	
136	/**
137	 * Policy-wide modifiers: each is charged as a percentage of the POLICY BASE
138	 * premium (the sum of item base premiums, before any item surcharge), so no
139	 * modifier is ever computed on top of another. Discounts carry a negative rate.
140	 */
141	const POLICY_MODIFIERS: {
142	  appliesTo: (customer: Customer) => boolean;
143	  rate: number;
144	}[] = [
145	  { appliesTo: () => true, rate: FIRST_INSURANCE_SURCHARGE_PERCENT },
146	  {
147	    appliesTo: (customer) =>
148	      customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS,
149	    rate: -LOYALTY_DISCOUNT_PERCENT,
150	  },
151	];
152	
153	const sumOfPolicyAdjustments = (
154	  customer: Customer,
155	  policyBasePremium: number,
156	): number =>
157	  POLICY_MODIFIERS.filter(({ appliesTo }) => appliesTo(customer)).reduce(
158	    (sum, { rate }) => sum + percent(policyBasePremium, rate),
159	    0,
160	  );
161	
162	const premiumFor = (customer: Customer, items: Item[]): number => {
163	  const policyBasePremium = sumOfBasePremiums(items);
164	  return Math.ceil(
165	    policyBasePremium +
166	      sumOfItemSurcharges(items) +
167	      sumOfPolicyAdjustments(customer, policyBasePremium) +
168	      PROCESSING_FEE,
169	  );
170	};
171	
172	export const runScenario = (scenario: Scenario): ScenarioResult => {
173	  const quote = scenario.steps[0] as QuoteStep;
174	  return {
175	    results: [{ premium: premiumFor(scenario.customer, quote.items) }],
176	  };
177	};
